"use strict";(self.webpackChunkenablemodel=self.webpackChunkenablemodel||[]).push([[2948],{3558:(e,t,a)=>{a.r(t),a.d(t,{assets:()=>h,contentTitle:()=>r,default:()=>l,frontMatter:()=>o,metadata:()=>i,toc:()=>c});var i=a(5780),s=a(4848),n=a(8453);const o={slug:"positionality",title:"Positionality in the ENABLE Model",authors:["lweru"]},r=void 0,h={authorsImageUrls:[void 0]},c=[{value:"What positionality requires in practice",id:"what-positionality-requires-in-practice",level:2},{value:"The grammar that enforces the position",id:"the-grammar-that-enforces-the-position",level:2},{value:"Artifacts have politics, and so do sentences about them",id:"artifacts-have-politics-and-so-do-sentences-about-them",level:2},{value:"The ENABLE Model is itself an artifact",id:"the-enable-model-is-itself-an-artifact",level:2},{value:"Why the grammar matters to the politics",id:"why-the-grammar-matters-to-the-politics",level:2},{value:"What readers can do with the position",id:"what-readers-can-do-with-the-position",level:2}];function d(e){const t={a:"a",em:"em",h2:"h2",p:"p",strong:"strong",...(0,n.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(t.p,{children:'A sentence that reads "Captions were not provided" names no one. A sentence that reads "The product team shipped the video without captions, and Deaf viewers relied on auto-generated transcripts that misnamed speakers" names the builder, the decision, the users, and the cost. The two sentences describe the same event. They commit the writer to different positions.'}),"\n",(0,s.jsx)(t.p,{children:'Donna Haraway argued in "Situated Knowledges" (1988) that no analytical account comes from nowhere. Every description of the world carries the reporter\'s location, interests, and responsibilities. The reporter who pretends otherwise tells the reader less, not more. Haraway named the alternative "situated knowledge": the reporter discloses the angle, the stake, and the limits, and accepts accountability for the partial view the reporter actually has. The ENABLE Model writes from that premise.'}),"\n",(0,s.jsx)(t.h2,{id:"what-positionality-requires-in-practice",children:"What positionality requires in practice"}),"\n",(0,s.jsxs)(t.p,{children:["James Charlton's ",(0,s.jsx)(t.em,{children:"Nothing About Us Without Us"})," (1998) took a disability rights movement slogan and elevated it into a principle of research ethics. The people most affected by an arrangement hold evidentiary authority about it. A researcher who writes about Deaf education without citing Deaf scholars and Deaf-led organizations has produced a weaker account, not a more objective one. The ENABLE Model routes through that principle in two ways. The ",(0,s.jsx)(t.a,{href:"/docs/category/manifestations",children:"manifestations corpus"})," documents what disabled people and their organizations have actually done, in their own words where possible and with verbatim quotation when cited. The analytical vocabulary names forces that disabled theorists identified, including Mike Oliver's social model of disability (",(0,s.jsx)(t.em,{children:"The Politics of Disablement"}),", 1990), Paul Farmer's structural violence (",(0,s.jsx)(t.em,{children:"Pathologies of Power"}),", 2003), Marta Russell's money model of disability (",(0,s.jsx)(t.em,{children:"Beyond Ramps"}),", 1998), Alison Kafer's curative imaginary (",(0,s.jsx)(t.em,{children:"Feminist, Queer, Crip"}),", 2013), and Sins Invalid's ten principles of disability justice (2015)."]}),"\n",(0,s.jsxs)(t.p,{children:["The positionality this implies is specific. Lawrence Weru writes the model from the position of a researcher trained at Harvard Medical School's Department of Global Health and Social Medicine, not from the position of the manifestations themselves. When a page describes ",(0,s.jsx)(t.a,{href:"/docs/manifestations/nike",children:"Nike's FlyEase"})," or ",(0,s.jsx)(t.a,{href:"/docs/forces-that-disable/disability-dongles",children:"AccessiBe's overlay"}),", the page names what third-party journalists, disability organizations, and users have observed. The page does not reproduce the company's marketing language. When Nike's own press materials appear as sources, they appear as claims the company makes about itself, not as neutral description."]}),"\n",(0,s.jsx)(t.h2,{id:"the-grammar-that-enforces-the-position",children:"The grammar that enforces the position"}),"\n",(0,s.jsx)(t.p,{children:"Grammar carries positionality the way camera angles carry a film's position. Four patterns in English writing about accessibility routinely erase actors, and the ENABLE Model cuts them all."}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"The linking verb with an abstract subject."}),' "AccessNow is an app that maps accessibility" treats the app as a self-subsisting object. The sentence suppresses the users who built the database, the disabled users who query it, and the accessibility inequities that made the app necessary. Maayan Ziv and her contributors built the AccessNow map because mainstream mapping products did not flag step-free entries or accessible bathrooms. Disabled travelers query the map because they would otherwise arrive at restaurants that turn them away. The active-voice sentence does more analytical work than the stative one.']}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"The passive without an agent."}),' "Accessibility features were added" never names who added them, when, or under what pressure. "Microsoft shipped Narrator in Windows 2000 after the National Federation of the Blind organized a multi-year campaign" names the actor, the artifact, the year, and the pressure that produced the shipping decision. The active-voice sentence is longer, but more useful.']}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"The noun-phrase conversion."}),' "The commitment to inclusion" converts a verb (commit) into a noun (commitment) that hovers in the sentence without requiring anyone to have committed anything. Disability studies calls this move "nominalization," and it routinely allows organizations to claim action they have not taken. "The CEO committed to inclusion in the 2021 annual report and defunded the accessibility team in 2023" names the two actions and lets the reader weigh them against each other.']}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"The category name as grammatical subject."}),' "Disability justice frameworks hold that access is collective" attributes an argument to a category instead of to the people who made the argument. Sins Invalid\'s ten principles, published in 2015 under the title ',(0,s.jsx)(t.em,{children:"Skin, Tooth, and Bone"}),', name interdependence as a core commitment. Mia Mingus\'s 2011 essay "Access Intimacy: The Missing Link" describes access as relational labor. Both of these citations do work that "disability justice frameworks" cannot do. They name the actor, the venue, the year, and the text a reader can consult.']}),"\n",(0,s.jsx)(t.h2,{id:"artifacts-have-politics-and-so-do-sentences-about-them",children:"Artifacts have politics, and so do sentences about them"}),"\n",(0,s.jsx)(t.p,{children:"Langdon Winner's 1980 essay \"Do Artifacts Have Politics?\" argued that technical objects embody political relationships in their design. Winner's central case cited Robert Moses, who built the parkway bridges over Long Island's Southern State Parkway deliberately low so that public buses could not pass underneath, which kept Black and low-income New Yorkers who depended on those buses off the beaches at Jones Island. The bridge is not neutral infrastructure that some groups happen to use less. The bridge is a policy cast in concrete, and it operates twenty-four hours a day without a single additional decision from Moses."}),"\n",(0,s.jsxs)(t.p,{children:['The accessibility artifact operates the same way. A CAPTCHA that offers no audio alternative, a PDF export that strips its tag tree, a form that binds its submit button to a mouseover handler, a video player that plays captions in a font the user cannot resize. Each of these objects makes a decision about who counts as a user, and each one keeps making that decision on every page load. Ruha Benjamin named this pattern "The New Jim Code" in ',(0,s.jsx)(t.em,{children:"Race After Technology"})," (2019), documenting how default settings, training data, and interface choices reproduce racial hierarchy while wearing the appearance of neutrality. Benjamin's examples include risk-assessment algorithms that encode historical policing patterns and facial-recognition systems trained on skewed datasets. The disability analog is direct. A screen reader that cannot parse a dynamic dropdown, a keyboard trap on a modal, a color contrast ratio below 4.5 to 1, a Google search result whose alt text field sat empty when the engineer shipped. Each artifact concentrates the cost of its political decision on the users the decision excludes."]}),"\n",(0,s.jsx)(t.p,{children:'Winner and Benjamin established that the artifact is already political before the writer reaches for a sentence to describe it. A writer who then describes that artifact in stative, passive, nominalized, or category-subject grammar performs a second political act. The artifact conceals its politics behind the appearance of neutral infrastructure, and the sentence conceals the artifact\'s politics behind the appearance of neutral description. The two concealments compound. Winner\'s Moses bridges read as "low bridges" on a highway map the same way "accessibility features were added" reads as a fact report in a quarterly earnings call. Both framings protect the decision-maker from accountability by presenting the decision as if it were a property of the thing rather than the action of a person.'}),"\n",(0,s.jsx)(t.p,{children:"The ENABLE Model's grammar refuses the second concealment, which is the one a writer controls. Naming the builder, the decision, the artifact, and the users affected does not by itself dismantle the artifact. It does make the artifact's politics visible, which is the condition a reader needs before challenging, reversing, or replacing it."}),"\n",(0,s.jsx)(t.h2,{id:"the-enable-model-is-itself-an-artifact",children:"The ENABLE Model is itself an artifact"}),"\n",(0,s.jsx)(t.p,{children:"Winner's argument turns recursively on any account that uses it. If bridges have politics and sentences have politics, then a model that describes bridges and sentences also has politics. The ENABLE Model is not standing outside the arrangement it describes. It is another built thing, with a frontmatter schema, a taxonomy of ten builder-side interventions and nine navigator-side compensations, a set of forces that disable and enable, a manifestations corpus, a writing rulebook, a website hosted on GitHub Pages, and a domain name. Each of those choices embeds a decision about what counts as evidence, what counts as a unit of analysis, and what counts as a valid claim."}),"\n",(0,s.jsx)(t.p,{children:"The taxonomy cuts the world in a specific way. The ten builder-side categories draw a boundary around what counts as upstream care, and a practice that sits between two categories, for example ongoing maintenance of a legacy screen-reader driver, has to be assigned to one of them or split across them. The nine navigator-side categories do the same on the other side. The model's frontier paragraph requires every manifestation to close by naming what advances the state of the possible, which commits the analysis to a progress vocabulary a reader may or may not accept. The ENABLE acronym itself names \"Early Neglect Allows Barriers\" and \"End-users Navigate Asymmetrical Barriers,\" which frames accessibility through neglect and labor rather than through, for example, an identity-first or rights-first vocabulary another tradition might prefer. Lawrence Weru built the model after training that crossed several Harvard departments and a cross-registration at MIT. The capstone landed in Harvard Medical School's Department of Global Health and Social Medicine, which carries Paul Farmer's structural violence and the resocializing disciplines through the analysis. Weru also worked as a researcher at Harvard Medical School's Department of Biomedical Informatics, which shapes the model's attention to systems, data, and the artifacts that carry both. He took undergraduate courses in Harvard's Anthropology department, including Harvard's only anthropology course on disability and the body, and a disability law and policy course at the Harvard Kennedy School. MIT cross-registration added the STS tradition that reads technology as politics, which is why Winner and Benjamin sit comfortably alongside Mike Oliver, Marta Russell, Alison Kafer, Mia Mingus, and Sins Invalid in the citation pattern. The model's analytical lineage draws from all of those trainings. Another reader with a different training, for example a graduate of a deaf studies program, a disability-led cooperative, or a community organizing school, would write a different model. The site runs in English, on GitHub Pages, with footnote-driven citations and a Docusaurus-generated sidebar. Each of those choices is a convenience for some readers and a barrier for others."}),"\n",(0,s.jsx)(t.p,{children:"The manifestations corpus takes evidence from wherever the arrangement was actually documented. Mainstream journalism, specialist publications, disability-led blogs and newsletters, self-advocacy podcasts, oral history interviews, community forums and Discord archives, court records, government filings, and academic papers all qualify as third-party sources when they document what actors did. Community-documented evidence is often the only evidence that reached the arrangement at all, and the model treats it accordingly. The reflexive limit the corpus still carries is reach. A contributor has to find the evidence and write the page, and arrangements that no contributor has yet documented stay invisible to the corpus until someone does that work."}),"\n",(0,s.jsx)(t.p,{children:"The reflexive move Winner demands is to read the model the same way the model reads the artifacts it catalogs. Which decisions did its builder make, in whose interest, at whose cost? Who does the taxonomy exclude? What evidentiary standards concentrate authority in certain kinds of sources? Whose analytical traditions does the model lean on, and whose does it treat as adjacent rather than constitutive? The positionality post exists to invite that reading rather than to preempt it. A model about artifacts that refused to examine itself as an artifact would reproduce exactly the concealment Winner and Benjamin named. Readers who find the model useful should also find its choices contestable. Readers who find a category, a frontier requirement, or an evidentiary standard wrong for their case have identified a limit of this artifact, and those limits are where the next version of the model, or the next model entirely, starts."}),"\n",(0,s.jsx)(t.h2,{id:"why-the-grammar-matters-to-the-politics",children:"Why the grammar matters to the politics"}),"\n",(0,s.jsx)(t.p,{children:"A writer who lets organizations describe themselves through linking verbs produces promotional prose. A writer who lets passive constructions hide actors produces compliance prose. A writer who converts verbs into nouns produces management consulting prose. None of those registers suit an ethnography of accessibility, because all of them protect the actors whose decisions the ethnography must name."}),"\n",(0,s.jsx)(t.p,{children:"The active-voice, named-actor grammar the ENABLE Model uses accomplishes three things at once. It discloses Weru's position as the reporter who observed this arrangement. It preserves the agency of disabled users who are navigating, compensating, organizing, and enduring. And it forces the question that an ethnography of care should always force. Who decided, in whose interest, at whose cost?"}),"\n",(0,s.jsx)(t.h2,{id:"what-readers-can-do-with-the-position",children:"What readers can do with the position"}),"\n",(0,s.jsxs)(t.p,{children:['The ENABLE Model\'s grammar is not a style preference. It is the minimum the work can do to honor the positionality it claims. Readers who use the model in their own writing, whether on a blog, in a legal brief, in a design review, or in a policy memo, can adopt the same grammar and produce the same analytical clarity. A complaint letter that names the specific product manager, the specific decision, the specific date, and the specific users affected travels further than one that invokes "the lack of accessibility." A design review that names the teammates who flagged the issue, the sprint in which the decision was made, and the disabled user who will ',(0,s.jsx)(t.a,{href:"/docs/navigator-side/switch-to-alternative",children:"switch to an alternative"}),' if the fix ships late produces a better conversation than one that says "we need to prioritize accessibility."']}),"\n",(0,s.jsx)(t.p,{children:"The grammar is the politics, in compressed form. The ENABLE Model writes it that way because accessibility work that does not know where it stands cannot discern what it is seeing."})]})}function l(e={}){const{wrapper:t}={...(0,n.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(d,{...e})}):d(e)}},5780:e=>{e.exports=JSON.parse('{"permalink":"/blog/positionality","editUrl":"https://github.com/facebook/docusaurus/tree/main/packages/create-docusaurus/templates/shared/blog/2025-11-11-positionality.md","source":"@site/blog/2025-11-11-positionality.md","title":"Positionality in the ENABLE Model","description":"A sentence that reads \\"Captions were not provided\\" names no one. A sentence that reads \\"The product team shipped the video without captions, and Deaf viewers relied on auto-generated transcripts that misnamed speakers\\" names the builder, the decision, the users, and the cost. The two sentences describe the same event. They commit the writer to different positions.","date":"2025-11-11T00:00:00.000Z","tags":[],"readingTime":11.19,"hasTruncateMarker":true,"authors":[{"name":"Lawrence (Larry) Weru","title":"Discerner-Uniter","url":"https://lweru.com","page":{"permalink":"/blog/authors/all-larry-weru-articles"},"imageURL":"https://github.com/LDubya.png","key":"lweru"}],"frontMatter":{"slug":"positionality","title":"Positionality in the ENABLE Model","authors":["lweru"]},"unlisted":false,"nextItem":{"title":"Contributing Manifestations to the ENABLE Model","permalink":"/blog/investigating-contributing-manifestations"}}')},8453:(e,t,a)=>{a.d(t,{R:()=>o,x:()=>r});var i=a(6540);const s={},n=i.createContext(s);function o(e){const t=i.useContext(n);return i.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:o(e.components),i.createElement(n.Provider,{value:t},e.children)}}}]);